def calculate_checksum(header_bytes):
    """Calculate IPv6 header checksum (pseudo-header style not needed for IPv6, but Fragment Header has no checksum).
    Note: IPv6 headers do not have a checksum. The upper-layer protocol handles it.
    We just return 0 for the Fragment Header as it has no checksum field."""
    return 0

def craft_ipv6_fragment(src_ip, dst_ip, identification, fragment_offset, more_fragments, payload):
    """
    Crafts an IPv6 packet with a Fragment Header.
    
    Args:
        src_ip: Source IPv6 address string
        dst_ip: Destination IPv6 address string
        identification: 32-bit fragment identification
        fragment_offset: 13-bit fragment offset (in 8-octet units)
        more_fragments: Boolean, True if more fragments follow
        payload: Bytes to include in the fragment
    """
    # IPv6 Header Structure:
    # Version(4) | Traffic Class(8) | Flow Label(20) | Payload Length(16) | Next Header(8) | Hop Limit(8)
    # Source Address (128) | Destination Address (128)
    
    version_traffic_class = 0x6000  # Version 6, TC 0
    flow_label = 0
    next_header = 44  # Fragment Header
    hop_limit = 64
    
    # Payload length includes Fragment Header (8 bytes) + payload
    payload_length = 8 + len(payload)
    
    ipv6_header = struct.pack('!BBHHH16s16s',
        (version_traffic_class >> 8) & 0xFF,  # Version & TC
        version_traffic_class & 0xFF,
        flow_label >> 8,                      # Flow Label
        flow_label & 0xFF,
        payload_length,
        next_header,
        hop_limit,
        socket.inet_pton(socket.AF_INET6, src_ip),
        socket.inet_pton(socket.AF_INET6, dst_ip)
    )
    
    # Fragment Header Structure:
    # Next Header(8) | Reserved(8) | Fragment Offset(13) | Res(2) | M(1)
    # Identification (32)
    
    # Calculate the 32-bit field containing Offset, Res, M
    # Offset is 13 bits, Res is 2 bits, M is 1 bit
    frag_header_field = (fragment_offset << 3) | (0 << 2) | (1 if more_fragments else 0)
    
    # Next Header for the fragmentable part (e.g., UDP=17, TCP=6, ICMPv6=58)
    # We'll use UDP (17) for simplicity as the upper layer
    next_header_frag = 17 
    
    fragment_header = struct.pack('!BBHI',
        next_header_frag,
        0,  # Reserved
        frag_header_field,
        identification
    )
    
    return ipv6_header + fragment_header + payload

def send_fragmented_packet(src_ip, dst_ip, identification, fragments):
    """
    Sends a series of IPv6 fragments.
    
    Args:
        src_ip: Source IPv6 address
        dst_ip: Destination IPv6 address
        identification: 32-bit ID for the fragment group
        fragments: List of tuples (offset, more_fragments, payload)
    """
    # Create raw socket
    sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
    
    # Disable automatic checksum calculation for IPv6 (though IPv6 header has none,
    # some OSs might try to handle it for extension headers or upper layers)
    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_CHECKSUM, 0)
    
    try:
        for offset, more_frags, payload in fragments:
            packet = craft_ipv6_fragment(src_ip, dst_ip, identification, offset, more_frags, payload)
            sock.sendto(packet, (dst_ip, 0, 0, 0))
            print(f"Sent fragment: Offset={offset}, More={more_frags}, PayloadLen={len(payload)}")
    finally:
        sock.close()

